//! The curves the contour's `shape` and `smoothness` read, generated by
//! our own code from the formulas in Mutable Instruments'
//! `tides2/resources/lookup_tables.py` (MIT, Copyright 2017 Emilie
//! Gillet). See THIRD_PARTY_NOTICES.md.
//!
//! They are built once, in `f64`, the first time a contour is built on the
//! control thread ([`force`]); the audio thread only reads them.

use std::f64::consts::PI;
use std::sync::LazyLock;

/// Steps across one shaping curve's input, 0 to 1.
pub(super) const CURVE_STEPS: usize = 1024;
/// Entries in one curve: one per step and the end point.
const CURVE_SIZE: usize = CURVE_STEPS + 1;
/// The audio-rate curves, which map 0..1 onto 0..1 and suit a cycle that
/// rises and falls: inverse tangent, inverse sine, linear, sine, bump.
pub(super) const AUDIO_CURVES: usize = 5;
/// The control-rate curves, each an attack over the first half of the
/// input and a decay over the second: logarithmic, logarithmic with a
/// mirrored decay, inverse sine, linear, sine, exponential with a mirrored
/// decay, exponential.
pub(super) const CONTROL_CURVES: usize = 7;
const CURVES: usize = AUDIO_CURVES + CONTROL_CURVES;
/// Entries in a fold table: the steps across its input and three more, so
/// interpolation can read one past the end.
const FOLD_SIZE: usize = CURVE_STEPS + 4;

pub(super) struct Tables {
    /// Every curve, end to end: the audio curves, then the control curves.
    /// Neighbouring curves are crossfaded, so their order is the order
    /// `shape` sweeps through.
    curves: [f32; CURVES * CURVE_SIZE],
    /// A fold for a bipolar cycle: a sine that folds near the middle of
    /// the range, easing into an arctangent toward the edges.
    bipolar_fold: [f32; FOLD_SIZE],
    /// The same idea for a unipolar envelope.
    unipolar_fold: [f32; FOLD_SIZE],
}

static TABLES: LazyLock<Tables> = LazyLock::new(build);

/// The tables, built on first use.
pub(super) fn tables() -> &'static Tables {
    &TABLES
}

/// Builds the tables now, so the audio thread never does.
pub(super) fn force() {
    LazyLock::force(&TABLES);
}

impl Tables {
    /// `input` (0..1) through curve `curve`, crossfaded `blend` (0..1) of
    /// the way to the next curve.
    #[inline]
    pub(super) fn shape(&self, input: f32, curve: usize, blend: f32) -> f32 {
        let index = CURVE_STEPS as f32 * input;
        let whole = index as usize;
        let frac = index - whole as f32;
        // Input 1 reads the start of the curve again, as the end of a
        // cycle is the start of the next.
        let at = curve.min(CURVES - 2) * CURVE_SIZE + (whole & (CURVE_STEPS - 1));
        let lerp = |a: f32, b: f32, t: f32| a + (b - a) * t;
        let this = lerp(self.curves[at], self.curves[at + 1], frac);
        let next = lerp(
            self.curves[at + CURVE_SIZE],
            self.curves[at + CURVE_SIZE + 1],
            frac,
        );
        lerp(this, next, blend)
    }

    /// `bipolar` (−1..1) folded `amount` (0..1) of the way.
    #[inline]
    pub(super) fn fold_bipolar(&self, bipolar: f32, amount: f32) -> f32 {
        if amount <= 0.0 {
            return bipolar;
        }
        let folded = interpolate(&self.bipolar_fold, 0.5 + bipolar * (0.03 + 0.46 * amount));
        bipolar + (folded - bipolar) * amount
    }

    /// `unipolar` (0..1) folded `amount` (0..1) of the way.
    #[inline]
    pub(super) fn fold_unipolar(&self, unipolar: f32, amount: f32) -> f32 {
        if amount <= 0.0 {
            return unipolar;
        }
        let folded = interpolate(&self.unipolar_fold, unipolar * amount);
        unipolar + (folded - unipolar) * amount
    }
}

/// `table` read at `position` (0..1 across its steps), interpolated.
#[inline]
fn interpolate(table: &[f32; FOLD_SIZE], position: f32) -> f32 {
    let index = (position * CURVE_STEPS as f32).clamp(0.0, CURVE_STEPS as f32);
    let whole = index as usize;
    let frac = index - whole as f32;
    table[whole] + (table[whole + 1] - table[whole]) * frac
}

fn build() -> Tables {
    let mut curves = [0.0; CURVES * CURVE_SIZE];
    let audio: [&dyn Fn(f64) -> f64; AUDIO_CURVES] = [
        &inverse_tan,
        &|x| (1.0 - 2.0 * x).acos() / PI,
        &|x| x,
        &|x| 0.5 - 0.5 * (PI * x).cos(),
        &bump,
    ];
    for (k, curve) in audio.iter().enumerate() {
        let slot = &mut curves[k * CURVE_SIZE..(k + 1) * CURVE_SIZE];
        for (i, entry) in slot.iter_mut().enumerate() {
            let x = i.min(CURVE_STEPS - 1) as f64 / CURVE_STEPS as f64;
            *entry = curve(x) as f32;
        }
    }
    let expo_max = 1.0 - (-5.0 * (HALF - 1) as f64 / HALF as f64).exp();
    let expo = |x: f64| (1.0 - (-5.0 * x).exp()) / expo_max;
    let log = |x: f64| (1.0 - x * expo_max).ln() / -5.0;
    // Each control curve: its attack, and whether the decay retraces the
    // attack backwards (mirrored) or falls as its complement.
    let control: [(&dyn Fn(f64) -> f64, bool); CONTROL_CURVES] = [
        (&log, false),
        (&log, true),
        (&|x| (1.0 - 2.0 * x).acos() / PI, false),
        (&|x| x, false),
        (&|x| (1.0 - (PI * x).cos()) / 2.0, false),
        (&expo, true),
        (&expo, false),
    ];
    for (k, (attack, mirrored)) in control.iter().enumerate() {
        let start = (AUDIO_CURVES + k) * CURVE_SIZE;
        let slot = &mut curves[start..start + CURVE_SIZE];
        for (i, entry) in slot.iter_mut().enumerate() {
            let value = if i < HALF {
                attack(i as f64 / HALF as f64)
            } else if i == HALF {
                1.0
            } else if *mirrored {
                attack((CURVE_SIZE - 1 - i) as f64 / HALF as f64)
            } else {
                1.0 - attack((i - HALF - 1) as f64 / HALF as f64)
            };
            *entry = value as f32;
        }
    }
    Tables {
        curves,
        bipolar_fold: bipolar_fold(),
        unipolar_fold: unipolar_fold(),
    }
}

/// Half a control curve's steps: the attack's.
const HALF: usize = CURVE_STEPS / 2;

/// A curve that rushes up, flattens through the middle and rushes to the
/// top: the inverse of an arctangent bend.
fn inverse_tan(x: f64) -> f64 {
    if x == 0.0 {
        return 0.0;
    }
    let scale = 8.0f64.atan();
    ((scale * (1.0 - 2.0 * x)).tan() / 8.0)
        .clamp(-1.0, 1.0)
        .acos()
        / PI
}

/// A rise that overshoots and settles back, fading to nothing at the end.
fn bump(x: f64) -> f64 {
    let fade_crop = (4.0 - 4.0 * x).min(1.0);
    (1.0 - (PI * x * 1.5).cos()) * (1.0 - (PI * fade_crop).cos()) / 4.5
}

fn peak_normalised(raw: [f64; FOLD_SIZE]) -> [f32; FOLD_SIZE] {
    let peak = raw.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    raw.map(|v| (v / peak) as f32)
}

fn bipolar_fold() -> [f32; FOLD_SIZE] {
    let mut raw = [0.0; FOLD_SIZE];
    for (i, v) in raw.iter_mut().enumerate() {
        let x = i.min(FOLD_SIZE - 2) as f64 / (CURVE_STEPS as f64 / 2.0) - 1.0;
        let window = (-x * x * 4.0).exp().powi(2);
        *v = (8.0 * PI * x).sin() * window + (3.0 * x).atan() * (1.0 - window);
    }
    peak_normalised(raw)
}

fn unipolar_fold() -> [f32; FOLD_SIZE] {
    let mut raw = [0.0; FOLD_SIZE];
    for (i, v) in raw.iter_mut().enumerate() {
        let x = i.min(FOLD_SIZE - 3) as f64 / CURVE_STEPS as f64;
        let window = (-x * x * 4.0).exp().powi(2);
        *v = (0.38 * (16.0 * PI * x).sin() + 4.0 * x) * window + (4.0 * x).atan() * (1.0 - window);
    }
    peak_normalised(raw)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn audio_curves_run_from_zero_to_one() {
        let t = tables();
        for curve in 0..AUDIO_CURVES - 1 {
            assert!(t.shape(0.0, curve, 0.0).abs() < 1e-6, "curve {curve}");
            // The inverse tangent is still steepening at its last step.
            assert!(t.shape(0.999, curve, 0.0) > 0.9, "curve {curve}");
        }
        // The bump fades back to nothing at the end.
        assert!(t.shape(0.999, AUDIO_CURVES - 1, 0.0).abs() < 0.01);
    }

    #[test]
    fn control_curves_rise_to_one_at_half_and_fall_back() {
        let t = tables();
        for k in 0..CONTROL_CURVES {
            let curve = AUDIO_CURVES + k;
            assert!(t.shape(0.0, curve, 0.0).abs() < 1e-6, "curve {k} start");
            assert!(
                (t.shape(0.5, curve, 0.0) - 1.0).abs() < 1e-6,
                "curve {k} top"
            );
            // The logarithmic decay falls fastest at its end.
            assert!(t.shape(0.9995, curve, 0.0) < 0.15, "curve {k} end");
            // Monotonic up, then down.
            let mut last = 0.0;
            for i in 1..=512 {
                let v = t.shape(i as f32 / 1024.0, curve, 0.0);
                assert!(v >= last - 1e-6, "curve {k} rises at {i}");
                last = v;
            }
        }
    }

    #[test]
    fn folds_stay_within_their_range() {
        let t = tables();
        for i in 0..=2000 {
            let x = i as f32 / 1000.0 - 1.0;
            for amount in [0.0, 0.3, 1.0] {
                assert!(t.fold_bipolar(x, amount).abs() <= 1.0 + 1e-6);
                let u = (x + 1.0) / 2.0;
                let folded = t.fold_unipolar(u, amount);
                assert!(
                    (-1e-6..=1.0 + 1e-6).contains(&folded),
                    "{u} {amount} {folded}"
                );
            }
        }
    }
}
